# -------------------------
# 2. PROCESAR EL HTML
# -------------------------
soup = BeautifulSoup(html_data, "html.parser")

# Extraer lista de equipos desde la tabla de la parte fija (fixed-left)
left_table = soup.find("table", class_="Table Table--align-right Table--fixed Table--fixed-left")
teams = []
if left_table:
    tbody_left = left_table.find("tbody")
    if tbody_left:
        for tr in tbody_left.find_all("tr"):
            tds = tr.find_all("td")
            if len(tds) >= 2:
                # El segundo <td> contiene el nombre del equipo (limpiamos espacios)
                team_name = tds[1].get_text(strip=True)
                teams.append(team_name)

# Extraer encabezados y filas de estadísticas desde la tabla scroller
right_table_div = soup.find("div", class_="Table__Scroller")
headers = []
stats_rows = []
if right_table_div:
    right_table = right_table_div.find("table")
    if right_table:
        # Encabezados
        thead = right_table.find("thead")
        if thead:
            header_tr = thead.find("tr")
            if header_tr:
                for th in header_tr.find_all("th"):
                    headers.append(th.get_text(strip=True))
        # Filas de estadísticas
        tbody_right = right_table.find("tbody")
        if tbody_right:
            for tr in tbody_right.find_all("tr"):
                cells = [td.get_text(strip=True) for td in tr.find_all("td")]
                stats_rows.append(cells)

# Combinar ambos conjuntos (se asume que el orden coincide)
data = {}
for idx, team in enumerate(teams):
    if idx < len(stats_rows):
        # Crear un diccionario con cada estadística asociada a su encabezado
        stats_dict = dict(zip(headers, stats_rows[idx]))
        data[team] = stats_dict

# -------------------------
# 3. FUNCIONES AUXILIARES
# -------------------------
def to_float(value):
    """
    Convierte una cadena a float eliminando espacios, signos '+' y '%' y comas.
    Si no se puede convertir, retorna None.
    """
    try:
        value = value.strip().replace("+", "").replace("%", "").replace(",", "")
        return float(value)
    except:
        return None

# -------------------------
# 4. INTERACCIÓN CON EL USUARIO Y COMPARACIÓN
# -------------------------
print("Equipos disponibles:")
for team in data.keys():
    print(" -", team)

# Función para solicitar un equipo y validar que existe
def solicitar_equipo(prompt):
    equipo = input(prompt).strip()
    while equipo not in data:
        print("Equipo no encontrado. Intenta de nuevo. Equipos disponibles:")
        for t in data.keys():
            print(" -", t)
        equipo = input(prompt).strip()
    return equipo

equipo1 = solicitar_equipo("Ingrese el primer equipo: ")
equipo2 = solicitar_equipo("Ingrese el segundo equipo: ")

stats1 = data[equipo1]
stats2 = data[equipo2]

max_diff = -1
stat_mayor_diff = None
valor1 = None
valor2 = None

# Comparar cada estadística (se intenta convertir a número)
for stat in stats1:
    val1 = to_float(stats1[stat])
    val2 = to_float(stats2.get(stat, ""))
    # Si alguno no es numérico, se omite
    if val1 is None or val2 is None:
        continue
    diff = abs(val1 - val2)
    if diff > max_diff:
        max_diff = diff
        stat_mayor_diff = stat
        valor1 = val1
        valor2 = val2

if stat_mayor_diff:
    print("\nLa estadística con mayor diferencia es:")
    print(f"Estadística: {stat_mayor_diff}")
    print(f"{equipo1}: {valor1}")
    print(f"{equipo2}: {valor2}")
    print(f"Diferencia absoluta: {max_diff}")
else:
    print("No se pudieron comparar las estadísticas numéricas.")
